with g as (insert into public.galleries (slug,name,hero,intro,sort,published) values ('cars','Cars','/assets/img/491946_d69adddab4154cf994275ad430ec9941.jpg','<span>In every reflection, curve, and blur of motion lies a story of speed — paused in a single frame. This portfolio captures the <span class="green"><span>soul</span></span> of machines, the tension between movement and stillness, where energy meets silence.&nbsp;It’s a celebration of <span class="green"><span>design and momentum</span></span> — a moment where power, beauty, and stillness become one.</span>',1,true) returning id)
