with g as (insert into public.galleries (slug,name,hero,intro,sort,published) values ('urbex','Urbex','/assets/img/491946_bce490a0ebe24656ac3e9a83eab13a11.jpg','Hidden behind broken windows and forgotten walls lies a world <span class="green"><span>frozen in time</span></span>. Each abandoned place carries the whispers of stories long left behind — <span class="green"><span>echoes of life</span></span>, industry, and dreams now reclaimed by nature.&nbsp;Peeling paint becomes art, shattered glass reflects memories, and empty halls breathe with a haunting kind of beauty.',2,true) returning id)
