with g as (insert into public.galleries (slug,name,hero,intro,sort,published) values ('football','Football','/assets/img/491946_40efa32662e84640993fed44bb4687ff.jpg','<span><span><span><span><span>Every match is </span></span></span></span><span><span class="green"><span><span><span>more than just a game</span></span></span></span></span><span><span><span><span> — it’s emotion, rhythm, and the unspoken language of teamwork. From the first whistle to the last echo of the crowd, football is&nbsp;raw energy captured in motion.&nbsp;It’s the beauty of precision and chaos of competition. Every shot, every save, every celebration tells a story of strength, focus, and belief.</span></span></span></span></span>',3,true) returning id)
