with g as (insert into public.galleries (slug,name,hero,intro,sort,published) values ('icehockey','Ice Hockey','/assets/img/491946_ec755847da9d4d579b66150677c47dd0.jpg','<span><span class="green">Hockey is more than a game</span></span> — it’s a battle of speed, precision, and heart.&nbsp;Every shift on the ice is a clash of power and control, where seconds decide <span><span class="green">heroes</span></span> and silence breaks into thunder. The cold air bites, the skates carve, and the puck moves faster than thought — yet within the chaos, there’s beauty.',4,true) returning id)
