with g as (insert into public.galleries (slug,name,hero,intro,sort,published) values ('comicconprague','Comic-Con Prague','/assets/img/942fb7_1b0ef05f5acb45e88659a6c4c710c09c.webp','Meeting Ghost, Jack Sparrow, and other iconic characters from the <span><span class="green">world of games</span></span> and <span><span class="green">movies</span></span> all in <span class="green"><span>one day</span></span>? No problem at <span class="green"><span>Comic-C</span></span><span class="green"><span>on Prague</span></span>. Once again, the atmosphere was amazing – full of creative cosplays and passionate fans everywhere you looked. Here’s a <span class="green"><span>short photo report</span></span> from the event. I didn’t have as much time this year since I was also filming another fair during the same week, but still – a busy yet fantastic start to April, just the <span class="green"><span>way I like it</span></span>.',5,true) returning id)
